-- fix/ui_survey_r2.lua [UISURVEY2]: generated by tools/ui_survey_r2_build.py (base f714708e~1). Studio Edit, any place.
-- The UI survey round 2 changes as anchor edits on the live scripts (see the builder's docstring), then the place
-- patches (ui/matchplace/ui_survey_place.lua) and, in a match place, the UIStyleController / InterfaceController patches.
local CHS = game:GetService('ChangeHistoryService'); local rec = CHS:TryBeginRecording('UI survey r2')
local function at(path) local o = game; for p in path:gmatch('[^%.]+') do o = o and o:FindFirstChild(p) end; return o end
local report, bad = {}, 0
local function apply(path, edits)
	local s = at(path); if not s then return end
	local crlf = s.Source:find('\r\n', 1, true) ~= nil
	local src = s.Source:gsub('\r\n', '\n')
	local done, skip = 0, 0
	for i, e in edits do
		local o, n = e[1], e[2] -- (Lua drops the newline right after a long-bracket opener)
		-- an edit whose new text still holds its anchor is 'already in' when the new text is there (else it re-applied every run)
		local a = if n:find(o, 1, true) and src:find(n, 1, true) then nil else src:find(o, 1, true)
		if a and src:find(o, a + 1, true) then table.insert(report, path .. ' edit ' .. i .. ': anchor x2'); bad += 1; return end
		if a then src = src:sub(1, a - 1) .. n .. src:sub(a + #o); done += 1
		elseif src:find(n, 1, true) then skip += 1
		else table.insert(report, path .. ' edit ' .. i .. ': anchor missing'); bad += 1; return end
	end
	if crlf then src = src:gsub('\n', '\r\n') end
	s.Source = src
	table.insert(report, path:match('[^%.]+$') .. ' ' .. done .. ' applied / ' .. skip .. ' already in')
end
